import {parseCoordinates} from './free-map.mjs';
const cache=new Map();
export function resultsFrom(data){return (data.features||[]).flatMap(f=>{const [lng,lat]=f.geometry?.coordinates||[];if(!parseCoordinates(`${lat},${lng}`))return [];const p=f.properties||{};const title=p.name||[p.street,p.housenumber].filter(Boolean).join(' ');const detail=[p.district,p.city,p.state,p.country].filter(Boolean).filter((v,i,a)=>a.indexOf(v)===i).join(', ');return title?[{lat,lng,title,detail,label:[title,detail].filter(Boolean).join(', ')}]:[];});}
export function attachSearch(input,onSelect){
 const wrap=document.createElement('div');wrap.className='address-search';input.parentNode.insertBefore(wrap,input);wrap.append(input);
 const list=document.createElement('div');list.id=input.id+'-options';list.className='address-options';list.role='listbox';list.hidden=true;wrap.append(list);
 const status=document.createElement('div');status.className='search-status';status.setAttribute('role','status');wrap.append(status);
 input.autocomplete='off';input.setAttribute('role','combobox');input.setAttribute('aria-autocomplete','list');input.setAttribute('aria-controls',list.id);input.setAttribute('aria-expanded','false');
 let timer,controller,version=0,items=[],active=-1;
 function close(){list.hidden=true;input.setAttribute('aria-expanded','false');input.removeAttribute('aria-activedescendant');active=-1;}
 function cancel(){clearTimeout(timer);controller?.abort();version++;close();status.textContent='';}
 function pick(i){const item=items[i];if(!item)return;cancel();input.value=item.label;onSelect(item);status.textContent='Location selected. Pin updated on the map.';}
 function render(rows){items=rows;list.replaceChildren();active=-1;if(!rows.length){close();status.textContent='No matches. Add a district or city, or pick a point on the map.';return;}for(const [i,r] of rows.entries()){const option=document.createElement('div');option.id=list.id+'-'+i;option.role='option';option.setAttribute('aria-selected','false');option.className='address-option';const title=document.createElement('strong');title.textContent=r.title;const detail=document.createElement('small');detail.textContent=r.detail;option.append(title,detail);option.addEventListener('pointerdown',e=>e.preventDefault());option.addEventListener('click',()=>pick(i));list.append(option);}list.hidden=false;input.setAttribute('aria-expanded','true');status.textContent='Suggestions by Photon / OpenStreetMap';}
 input.addEventListener('input',()=>{cancel();const q=input.value.trim();if(q.length<3||parseCoordinates(q))return;const current=version;timer=setTimeout(async()=>{status.textContent='Searching places…';controller=new AbortController();const timeout=setTimeout(()=>controller?.abort(),10000);try{let rows=cache.get(q);if(!rows){const url=new URL('https://photon.komoot.io/api/');url.search=new URLSearchParams({q,limit:'6',lat:'39',lon:'32',lang:'en'});const response=await fetch(url,{signal:controller.signal});if(!response.ok)throw Error('Search unavailable');rows=resultsFrom(await response.json());if(cache.size>=60)cache.delete(cache.keys().next().value);cache.set(q,rows);}if(current===version&&document.activeElement===input)render(rows);}catch(e){if(current===version){close();status.textContent='Search is temporarily unavailable. Try again, enter an address, or pick a map point.';}}finally{clearTimeout(timeout);}},550);});
 input.addEventListener('keydown',e=>{if(e.key==='Escape'){cancel();return;}if(list.hidden)return;if(e.key==='ArrowDown'||e.key==='ArrowUp'){e.preventDefault();active=(active+(e.key==='ArrowDown'?1:-1)+items.length)%items.length;[...list.children].forEach((el,i)=>el.setAttribute('aria-selected',String(i===active)));input.setAttribute('aria-activedescendant',list.children[active].id);list.children[active].scrollIntoView({block:'nearest'});}else if(e.key==='Enter'&&active>=0){e.preventDefault();pick(active);}});
 input.addEventListener('blur',()=>{cancel();});
 return {clear:cancel};
}
